class ThemeManager{constructor(){this.STORAGE_KEY="__METOR_CONFIG__",this.DEFAULT_THEME="light",this.THEME_ATTR="data-bs-theme",this.html=document.documentElement,this.defaultConfig={theme:"light",topbar:{color:"topbar-dark"},menu:{size:"default",color:"sidebar-light"}},this.config=this.loadConfig(),this.applyConfig(),this.initThemeToggle()}loadConfig(){try{var t=sessionStorage.getItem(this.STORAGE_KEY);if(t){var e=JSON.parse(t),i={...e,theme:document.documentElement.getAttribute("data-bs-theme")??e.theme};return Object.assign(structuredClone(this.defaultConfig),i)}}catch(t){sessionStorage.removeItem(this.DEFAULT_THEME)}return{...this.defaultConfig}}saveConfig(){try{sessionStorage.setItem(this.STORAGE_KEY,JSON.stringify(this.config))}catch(t){console.error("Failed to save theme config",t)}}applyConfig(){var{theme:t,topbar:e,menu:i}=this.config;this.html.classList.remove("topbar-dark","topbar-light","sidebar-dark","sidebar-light"),this.html.setAttribute("data-bs-theme",t),this.html.classList.add(e.color),this.html.classList.add(i.color),window.innerWidth<=1140&&this.html.classList.add("sidebar-hidden")}applyTheme(t){document.documentElement.setAttribute(this.THEME_ATTR,t)}changeThemeMode(t){this.applyTheme(t),this.config.theme=t,this.saveConfig(),this.applyConfig()}initThemeToggle(){window.addEventListener("load",()=>{const t=document.getElementById("light-dark-mode");t&&t.addEventListener("click",()=>{var t="light"===this.config.theme?"dark":"light";this.changeThemeMode(t)})})}}new ThemeManager;